import { Container, ContainerModule } from 'inversify';
import { VueConstructor } from 'vue';

import { SoundManager } from '@game-studio/sound-manager';
import { ICurrencySettings } from '@game-studio/utilities';
import { ICabinetConfig } from '@game-studio/cabinet';
import { GameConnection } from '@game-studio/shell-connection';
import { AssetData } from '@game-studio/asset-manager';

import { ICurrencyFormatter } from '../currency/currency-formatter';
import { BaseCabinet, ICabinetOptions } from '../cabinet/base-cabinet';
import { Stake } from '../cabinet/stake';
import { Injects } from '../inversify/injects';
import { IAdminSettings, IBaseDataList, IBaseDebugModel, IBaseGameModel, IBaseGameSettingsModel, IBaseLog, IDisplayConfig, IEndpoints, IGameServer, ILooseObject, ISkinDesc, IStrings, ITranslationVersions, SettingsConfig } from '../types';
import { IBigWinBase } from '../views/big-win/big-win';
import { containerModule as InitialBindings } from './bindings';
import { gameConfig } from '../models/config-model';
import { OperatorModel } from '../models/operator-model';
import { GameConfigProvider } from '../services/game-config-provider';

class DIContainer extends Container {
    constructor() {
        super({
            skipBaseClassChecks: true,
            autoBindInjectable: true
        });
    }

    public get frameConnection(): GameConnection {
        return this.get<GameConnection>(Injects.FrameConnection);
    }

    public get cabinetConfig(): ICabinetConfig {
        return this.get<ICabinetConfig>(Injects.CabinetConfig);
    }

    public get currencySettings(): ICurrencySettings {
        return this.get<ICurrencySettings>(Injects.CurrencySettings);
    }

    public get currencyFormatter(): ICurrencyFormatter {
        return this.get<ICurrencyFormatter>(Injects.CurrencyFormatter);
    }

    public get gameServer(): IGameServer {
        return this.get<IGameServer>(Injects.GameServer);
    }

    public get gameConfigProvider(): GameConfigProvider {
        return this.get<GameConfigProvider>(Injects.GameConfigProvider);
    }

    public get endPoints(): IEndpoints {
        return this.get<() => IEndpoints>(Injects.EndPointsFactory).call(this);
    }

    public get operatorModel(): OperatorModel {
        return this.get<OperatorModel>(Injects.OperatorModel);
    }

    public get strings(): IStrings {
        return this.get<IStrings>(Injects.Strings);
    }
    /** Game Server error messages for each code */
    public get errorStrings(): ILooseObject {
        return this.get<ILooseObject>(Injects.ErrorStrings);
    }

    public get cabinet(): BaseCabinet {
        return this.get<BaseCabinet>(Injects.Cabinet);
    }

    public get bigWin(): IBigWinBase {
        return this.get<IBigWinBase>(Injects.BigWin);
    }

    public get stake(): Stake {
        return this.get<Stake>(Injects.Stake);
    }

    /** Any settings loaded from the admin Panel  */
    public get adminSettings(): IAdminSettings {
        return this.get<IAdminSettings>(Injects.AdminSettings);
    }

    public get translationVersions(): ITranslationVersions | void {
        if (this.isBound(Injects.TranslationVersions)) {
            return this.get<ITranslationVersions>(Injects.TranslationVersions);
        }

        return;
    }

    /** Mobile-Web settings page configuration */
    public get settingsConfig(): SettingsConfig {
        if (this.isBound(Injects.SettingsConfig)) {
            return this.get<SettingsConfig>(Injects.SettingsConfig);
        }
        return {
            sections: [],
            sessionData: [],
            settingsVisibilites: {}
        };
    }

    /** Name to display on the mobile-web settings page */
    public get settingsPageGameName(): string {
        return this.get<string>(Injects.SettingsPageGameName);
    }

    public get chatRulesOverride(): VueConstructor<Vue> | null {
        if (this.isBound(Injects.ChatRulesOverride)) {
            return this.get<VueConstructor<Vue>>(Injects.ChatRulesOverride);
        } else {
            return null;
        }
    }

    public get gameVue(): VueConstructor<Vue> {
        return this.get<VueConstructor<Vue>>(Injects.GameComponent);
    }

    public get sessionDataVue(): VueConstructor<Vue> {
        return this.get<VueConstructor<Vue>>(Injects.SessionDataComponent);
    }

    public get desktopHtpVue(): VueConstructor<Vue> {
        return this.get<VueConstructor<Vue>>(Injects.DesktopHTPComponent);
    }

    public get mobileHtpVue(): VueConstructor<Vue> {
        return this.get<VueConstructor<Vue>>(Injects.MobileHTPComponent);
    }

    public get vueHtpVue(): VueConstructor<Vue> {
        return this.get<VueConstructor<Vue>>(Injects.VueHTPComponent);
    }

    public get desktopSettingsVue(): VueConstructor<Vue> {
        return this.get<VueConstructor<Vue>>(Injects.DesktopSettingsComponent);
    }

    public get mobileSettingsVue(): VueConstructor<Vue> {
        return this.get<VueConstructor<Vue>>(Injects.MobileSettingsComponent);
    }

    public get skin(): ISkinDesc {
        return this.get<ISkinDesc>(Injects.Skin);
    }

    public get localDataList(): AssetData {
        return this.get<AssetData>(Injects.LocalDataList);
    }

    public get coreDataList(): IBaseDataList {
        return this.get<IBaseDataList>(Injects.CoreDataList);
    }

    public get gameModel(): IBaseGameModel {
        return this.get<IBaseGameModel>(Injects.GameModel);
    }

    /** Settings of the game received in the resume request */
    public get gameSettings(): IBaseGameSettingsModel {
        return this.get<IBaseGameSettingsModel>(Injects.GameSettings);
    }

    public get debugModel(): IBaseDebugModel {
        return this.get<IBaseDebugModel>(Injects.DebugModel);
    }

    public get userPrefsGameName(): string {
        return this.get<string>(Injects.UserPrefsGameName);
    }

    public get soundManager(): SoundManager {
        return this.get<SoundManager>(Injects.SoundManager);
    }

    public get displayConfig(): IDisplayConfig | undefined {
        if (this.isBound(Injects.DisplayConfig)) {
            return this.get<IDisplayConfig>(Injects.DisplayConfig);
        }
        return void (0);
    }

    public get cabinetBaseOptions(): ICabinetOptions {
        return this.get<ICabinetOptions>(Injects.CabinetBaseOptions);
    }

    // public get apiClient(): IHostRequestAdapter | void {
    //     if (this.isBound(Injects.ApiClient)) {
    //         return this.get(Injects.ApiClient);
    //     }
    //     return void (0);
    // }

    public get CreateLogBody(): (...args: unknown[]) => IBaseLog {
        return this.get<(...args: unknown[]) => IBaseLog>(Injects.CreateLogBody);
    }

    /** Sets up the InversifyJS bindings for the engine and game to run */
    public async initialise(gameBindings: ContainerModule, regionBindings?: ContainerModule): Promise<void> {
        // Load default bindings
        this.load(InitialBindings);
        this.load(gameBindings);
        if (regionBindings) {
            // If there are any overwrites passed by the game rebind those
            this.load(regionBindings);
        }

        this.validateRequiredBindings();
    }

    /** Displays a clear error if any of the required bindings are not bound and prevets code execution and further errors */
    private validateRequiredBindings(): void {
        let failedBinding = '';

        const usingLocalAssets = gameConfig.features.usingLocalAssets;

        if (usingLocalAssets && !this.isBound(Injects.LocalDataList)) { throw new Error('LocalDataList not bound but you have \'usingLocalAssets\' enabled in your features.ts file.'); }

        if (!usingLocalAssets && !inversifyContainer.isBound(Injects.CoreDataList)) {
            failedBinding = 'CoreDataList';
        } else if (usingLocalAssets && !inversifyContainer.isBound(Injects.LocalDataList)) {
            failedBinding = 'LocalDataList'; 
        } else if (!inversifyContainer.isBound(Injects.GameModel)) {
            failedBinding = 'GameModel';
        } else if (!inversifyContainer.isBound(Injects.GameSettings)) {
            failedBinding = 'GameSettings';
        } else if (!inversifyContainer.isBound(Injects.DebugModel)) {
            failedBinding = 'DebugModel';
        } else if (!inversifyContainer.isBound(Injects.SkinFactory)) {
            failedBinding = 'SkinFactory';
        } else if (!inversifyContainer.isBound(Injects.ComponentsFactory)) {
            failedBinding = 'ComponentsFactory';
        } else if (!inversifyContainer.isBound(Injects.GameApp)) {
            failedBinding = 'GameApp';
        }

        if (failedBinding !== '') {
            const errorMessage = `${failedBinding} not bound, ensure you have bound ${failedBinding} in your inversify/bindings.ts file like below:\n\nbind(Injects.${failedBinding})...\n`;
            throw new Error(errorMessage);
        }
    }
}

export const inversifyContainer = new DIContainer();
